#include "platform_media.h"

#include <stddef.h>
#include <stdint.h>

#define PLATFORM_IMAGE_MAX_INPUT_BYTES (32U * 1024U * 1024U)
#define PLATFORM_IMAGE_MAX_PIXELS (64U * 1024U * 1024U)
