impl CFRange {
    /// Create a new [`CFRange`].
    #[doc(alias = "CFRangeMake")]
    pub fn new(location: CFIndex, length: CFIndex) -> Self {
        Self { location, length }
    }
}
    #[doc(alias = "retain")]
    #[inline]
    fn clone(&self) -> Self {
        self.retain()
    }
}

// Same as `objc::rc::Retained`, `#[may_dangle]` does not apply here.
impl<T: ?Sized> Drop for CFRetained<T> {
    /// Releases the contained type.
    #[doc(alias = "CFRelease")]
    #[doc(alias = "release")]
    #[inline]
    fn drop(&mut self) {
        extern "C-unwind" {
            fn CFRelease(cf: *mut c_void);
        }

        // SAFETY: The `ptr` is guaranteed to be valid, and have at least one
        // retain count.
        //
        // Note that `CFRelease` will abort if given a NULL pointer, but we
        // avoid that here by ensuring that the pointer is non-NULL.
        unsafe { CFRelease(self.ptr.as_ptr().cast()) };
    }
}

//! Safe boundary primitives for the native Apple implementation.
//!
//! This crate deliberately exposes no Objective-C pointer or fabricated
//! thread marker. Native calls and inbound callbacks should enter through
//! [`guard_native_call`], with callback adapters returning their ABI-valid
//! fallback after observing an error.

mod main_thread;
mod native_boundary;
mod native_window;

pub use main_thread::{MainThread, MainThreadError};
pub use native_boundary::{NativeFault, NativeFaultKind, guard_native_call};
pub use native_window::{Composition, Cursor, EventBatch, Modifiers, NativeApp, Point, PointerKind, PointerEvent, QueueFault, QueueFaultReason, Rect, ScrollEvent, Size, SizeU32, TextAttributeKind, TextAttributeSpan, TextInputState, Window, WindowConfig, WindowError, WindowEvent, WindowId};
        Ok(())
    }
    /// Internal presenter attachment seam. The crate-local presenter may attach
    /// a real layer to this retained NSView after handle validation; no pointer,
    /// fake presenter or rendering promise is exposed by the public API.
    #[allow(dead_code)]
    pub(crate) fn surface_view(&self) -> Result<Retained<NSView>, WindowError> {
        Ok(self.handles()?.view)
