use crate::tree::{Tree,TreeError,MAX_COMMANDS,MAX_NODES,MAX_TEXT_TOTAL_BYTES};

pub const MOD_SHIFT:u32=1;pub const MOD_COMMAND:u32=2;pub const MOD_OPTION:u32=4;pub const MOD_CONTROL:u32=8;
const MOD_MASK:u32=MOD_SHIFT|MOD_COMMAND|MOD_OPTION|MOD_CONTROL;

#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub struct CommandBinding{pub command_id:u32,pub key:u32,pub modifiers:u32,pub enabled:bool}
#[derive(Debug,Clone,PartialEq,Eq,Default)]pub struct CommandRegistry{bindings:Vec<CommandBinding>}
impl CommandRegistry{
    pub fn new()->Self{Self::default()}pub fn len(&self)->usize{self.bindings.len()}pub fn is_empty(&self)->bool{self.bindings.is_empty()}
    pub fn register(&mut self,command_id:u32,key:u32,modifiers:u32,enabled:bool)->Result<(),TreeError>{
        if command_id==0||key==0||modifiers&!MOD_MASK!=0{return Err(TreeError::InvalidInput)}
        if self.bindings.len()>=MAX_COMMANDS{return Err(TreeError::Capacity)}
        if self.bindings.iter().any(|b|b.command_id==command_id||(b.key==key&&b.modifiers==modifiers)){return Err(TreeError::DuplicateId)}
        self.bindings.try_reserve(1).map_err(|_|TreeError::Allocation)?;self.bindings.push(CommandBinding{command_id,key,modifiers,enabled});Ok(())
    }
    pub(crate) fn lookup(&self,key:u32,modifiers:u32)->Option<u32>{self.bindings.iter().find(|b|b.enabled&&b.key==key&&b.modifiers==modifiers).map(|b|b.command_id)}
}

