    pub id:u32,pub parent_id:u32,pub role:crate::Role,pub state:u32,pub command_id:u32,
    pub label_preview:String,pub value_preview:String,pub label:String,pub value:String,pub frame:crate::Rect,
}
#[derive(Debug,Clone,PartialEq,Eq,Default)]pub struct SemanticsSnapshot{pub nodes:Vec<SemanticsNode>,pub text_bytes_used:usize}
impl SemanticsSnapshot{
    pub(crate) fn from_tree(tree:&Tree)->Result<Self,TreeError>{
        if tree.nodes.len()>MAX_NODES||tree.text_bytes_used>MAX_TEXT_TOTAL_BYTES{return Err(TreeError::InvalidInput)}
        let mut out=Self::default();out.nodes.try_reserve_exact(tree.nodes.len()).map_err(|_|TreeError::Allocation)?;
        for source in &tree.nodes{
            let bytes=source.spec.label.len().checked_add(source.spec.value.len()).and_then(|n|out.text_bytes_used.checked_add(n)).filter(|n|*n<=MAX_TEXT_TOTAL_BYTES).ok_or(TreeError::TextLimit)?;
