            let mut value=String::new();value.try_reserve_exact(source.spec.value.len()).map_err(|_|TreeError::Allocation)?;value.push_str(&source.spec.value);
            let mut lp=String::new();lp.try_reserve_exact(source.label_preview.len()).map_err(|_|TreeError::Allocation)?;lp.push_str(&source.label_preview);
            let mut vp=String::new();vp.try_reserve_exact(source.value_preview.len()).map_err(|_|TreeError::Allocation)?;vp.push_str(&source.value_preview);
            out.nodes.push(SemanticsNode{id:source.spec.id,parent_id:source.spec.parent_id,role:source.spec.role,state:source.spec.state,command_id:source.spec.command_id,label_preview:lp,value_preview:vp,label,value,frame:source.bounds});out.text_bytes_used=bytes;
